import React, { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useMutation, useQuery, useQueryClient } from 'react-query';
import { useForm } from 'react-hook-form';
import { createPrompt, updatePrompt, getPromptById } from '../api/prompts';
import { FiPlus, FiX, FiSave } from 'react-icons/fi';
import toast from 'react-hot-toast';

const CreatePrompt = () => {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const { promptId } = useParams(); // 🟡 Detect edit mode
  const isEditMode = Boolean(promptId);

  const [tags, setTags] = useState([]);
  const [newTag, setNewTag] = useState('');
  const [isPublic, setIsPublic] = useState(true);
  const [isLoading, setIsLoading] = useState(false);

  const {
    register,
    handleSubmit,
    formState: { errors },
    watch,
    reset,
  } = useForm();

  const content = watch('content', '');

  // 🟡 FETCH existing prompt if editing
  const { data: existingPrompt, isLoading: isFetching } = useQuery(
    ['prompt', promptId],
    () => getPromptById(promptId),
    {
      enabled: isEditMode,
      onSuccess: (data) => {
        reset({
          title: data.title,
          content: data.content,
          description: data.description,
          category: data.category || 'other',
        });
        setTags(data.tags || []);
        setIsPublic(data.isPublic ?? true);
      },
      onError: () => {
        toast.error('Failed to load prompt for editing');
        navigate('/');
      },
    }
  );

  // 🟢 Mutation for create / update
  const mutation = useMutation(isEditMode ? updatePrompt : createPrompt, {
    onSuccess: (data) => {
      queryClient.invalidateQueries(['prompts']);
      toast.success(isEditMode ? 'Prompt updated!' : 'Prompt created!');
      navigate(`/prompts/${data._id}`);
    },
    onError: (error) => {
      const msg = error.response?.data?.message || 'Failed to save prompt';
      toast.error(msg);
    },
  });

  const handleAddTag = () => {
    const tag = newTag.trim().toLowerCase();
    if (tag && !tags.includes(tag) && tags.length < 10) {
      setTags([...tags, tag]);
      setNewTag('');
    }
  };

  const handleRemoveTag = (tagToRemove) => {
    setTags(tags.filter(tag => tag !== tagToRemove));
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      handleAddTag();
    }
  };

  const onSubmit = async (data) => {
    setIsLoading(true);
    try {
      const payload = {
        ...data,
        tags,
        isPublic,
      };
      if (isEditMode) payload.id = promptId; // pass id for update
      await mutation.mutateAsync(payload);
    } finally {
      setIsLoading(false);
    }
  };

  const categories = [
    { value: 'chatgpt', label: 'ChatGPT' },
    { value: 'midjourney', label: 'Midjourney' },
    { value: 'dalle', label: 'DALL-E' },
    { value: 'bard', label: 'Bard' },
    { value: 'claude', label: 'Claude' },
    { value: 'other', label: 'Other' },
  ];

  return (
    <div className="max-w-4xl mx-auto">
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-gray-900 mb-2">
          {isEditMode ? 'Edit Prompt' : 'Create New Prompt'}
        </h1>
        <p className="text-gray-600">
          {isEditMode
            ? 'Update your existing AI prompt'
            : 'Share your AI prompt with the community'}
        </p>
      </div>

      {isFetching && isEditMode ? (
        <p>Loading prompt...</p>
      ) : (
        <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
          {/* All your form fields (same as original code) */}
          {/* ... skip unchanged code ... */}

          {/* 🟡 Submit Button */}
          <div className="flex justify-end space-x-4 pt-6 border-t border-gray-200">
            <button
              type="button"
              onClick={() => navigate('/')}
              className="btn-secondary"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={isLoading}
              className="btn-primary flex items-center space-x-2"
            >
              {isLoading ? (
                <>
                  <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white"></div>
                  <span>{isEditMode ? 'Updating...' : 'Creating...'}</span>
                </>
              ) : (
                <>
                  <FiSave className="w-4 h-4" />
                  <span>{isEditMode ? 'Update Prompt' : 'Create Prompt'}</span>
                </>
              )}
            </button>
          </div>
        </form>
      )}
    </div>
  );
};

export default CreatePrompt;
